class Bird {

    String name = "Parakeet";
    String family = "Parrot";
    int age = 2;
    int cost = 7000;

    void makeSound() {
        System.out.println(name + " " + family + " is making sound");
    }

    void fly() {
        System.out.println(name + " " + family + " is flying");
    }
}

class BirdApp {

    public static void main(String[] args) {

        Bird bird1 = new Bird();

        System.out.println(
            bird1.name + " " +
            bird1.family + " " +
            bird1.age + " " +
            bird1.cost
        );

        bird1.makeSound();
        bird1.fly();

        Bird bird2 = new Bird();

        bird2.name = "Parity";
        bird2.family = "African Parrot";
        bird2.age = 3;
        bird2.cost = 30000;

        System.out.println(
            bird2.name + " " +
            bird2.family + " " +
            bird2.age + " " +
            bird2.cost
        );

        bird2.makeSound();
        bird2.fly();
    }
}

