class Calculator {

    int num1 = 10;
    int num2 = 20;

    void add() {
        System.out.println("Addition result is " + (num1 + num2));
    }

    void subtract() {
        System.out.println("Subtraction result is " + (num1 - num2));
    }

    void multiply() {
        System.out.println("Multiplication result is " + (num1 * num2));
    }

    void divide() {
        System.out.println("Division result is " + (num1 / num2));
    }

    void remainder() {
        System.out.println("Remainder result is " + (num1 % num2));
    }

    void average() {
        System.out.println("Average result is " + ((num1 + num2) / 2));
    }
}

class CalculatorApp {

    public static void main(String[] args) {

        Calculator casioCalci = new Calculator();

        casioCalci.num1 = 200;
        casioCalci.num2 = 100;

        casioCalci.add();
        casioCalci.subtract();
        casioCalci.multiply();
        casioCalci.divide();
        casioCalci.remainder();
        casioCalci.average();

        Calculator citizenCalci = new Calculator();

        citizenCalci.add();
        citizenCalci.subtract();
        citizenCalci.multiply();
        citizenCalci.divide();
        citizenCalci.remainder();
        citizenCalci.average();

        new Calculator().average();
    }
}

